int respace(char **dictionary, int dictionarySize, char *sentence) {
  int n = strlen(sentence);
  int *dp = (int *)malloc(sizeof(int) * (n + 1));
  dp[0] = 0;
  for (int i = 1; i <= n; i++) {
    dp[i] = dp[i - 1] + 1;
    for (int k = 0; k < dictionarySize; k++) {
      int wl = strlen(dictionary[k]);
      if (i >= wl && strncmp(sentence + i - wl, dictionary[k], wl) == 0) {
        if (dp[i - wl] < dp[i]) dp[i] = dp[i - wl];
      }
    }
  }
  int res = dp[n];
  free(dp);
  return res;
}

class Solution {
public:
  int respace(vector<string> &dictionary, string sentence) {
    unordered_set<string> words(dictionary.begin(), dictionary.end());
    int n = sentence.size();
    vector<int> dp(n + 1, 0);
    for (int i = 1; i <= n; i++) {
      dp[i] = dp[i - 1] + 1;
      for (const string &w : dictionary) {
        int wl = w.size();
        if (i >= wl && sentence.compare(i - wl, wl, w) == 0) {
          dp[i] = min(dp[i], dp[i - wl]);
        }
      }
    }
    return dp[n];
  }
};

func respace(dictionary []string, sentence string) int {
	n := len(sentence)
	dp := make([]int, n+1)
	for i := 1; i <= n; i++ {
		dp[i] = dp[i-1] + 1
		for _, w := range dictionary {
			wl := len(w)
			if i >= wl && sentence[i-wl:i] == w {
				if dp[i-wl] < dp[i] {
					dp[i] = dp[i-wl]
				}
			}
		}
	}
	return dp[n]
}

class Solution {
  public int respace(String[] dictionary, String sentence) {
    int n = sentence.length();
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
      dp[i] = dp[i - 1] + 1;
      for (String w : dictionary) {
        int wl = w.length();
        if (i >= wl && sentence.regionMatches(i - wl, w, 0, wl)) {
          dp[i] = Math.min(dp[i], dp[i - wl]);
        }
      }
    }
    return dp[n];
  }
}

class Solution:
    def respace(self, dictionary: List[str], sentence: str) -> int:
        n = len(sentence)
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = dp[i - 1] + 1
            for w in dictionary:
                wl = len(w)
                if i >= wl and sentence[i - wl:i] == w:
                    dp[i] = min(dp[i], dp[i - wl])
        return dp[n]

impl Solution {
  pub fn respace(dictionary: Vec<String>, sentence: String) -> i32 {
    let dict: HashSet<&str> = dictionary.iter().map(|s| s.as_str()).collect();
    let n = sentence.len();
    let mut dp = vec![0i32; n + 1];
    for i in 1..=n {
      dp[i] = dp[i - 1] + 1;
      for w in &dictionary {
        let wl = w.len();
        if i >= wl && &sentence[i - wl..i] == w.as_str() {
          dp[i] = dp[i].min(dp[i - wl]);
        }
      }
    }
    let _ = dict;
    dp[n]
  }
}

const respace = (dictionary: string[], sentence: string): number => {
  const n = sentence.length;
  const dp: number[] = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    dp[i] = dp[i - 1] + 1;
    for (const w of dictionary) {
      const wl = w.length;
      if (i >= wl && sentence.slice(i - wl, i) === w) {
        dp[i] = Math.min(dp[i], dp[i - wl]);
      }
    }
  }
  return dp[n];
};
